},
{
["recordedBy"] = "Nutellone-Draenor",
["typeInfo"] = {
["player"] = {
["name"] = "Image of Aegwynn",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Image of Aegwynn says: This hammer forged ancient wonders and shaped the earth itself. Today it shatters the bonds of fate that seek to crush us all.",
["id"] = "s0_133",
["timestamp"] = 1765113645,
},
{
["recordedBy"] = "Nutellone-Draenor",
["typeInfo"] = {
