},
["color"] = {
["b"] = 0.250980406999588,
["g"] = 0.250980406999588,
["r"] = 1,
},
["text"] = "Harjatan yells: Time to smash!",
["id"] = "s0_144",
["timestamp"] = 1765113686,
},
{
["recordedBy"] = "Nutellone-Draenor",
["typeInfo"] = {
["player"] = {
["name"] = "Archmage Khadgar",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Archmage Khadgar says: Heroes, the paths are open. Use the Pillars of Creation to bypass Aegwynn's wards before the Legion claims the avatar.",
["id"] = "s0_145",
["timestamp"] = 1765113686,
},
{
