["text"] = "Sathanes-Silvermoon receives item: |cnIQ4:|Hitem:246203::::::::80:104::133:5:12639:13524:13557:10034:6005:1:28:2905:::::|h[Chattering Soulmark]|h|r.",
["timestamp"] = 1765290300,
